<?php
if (function_exists("opcache_reset")) {
    @opcache_reset();
}
@header("X-LiteSpeed-Purge: *");

$locations = [
    __DIR__,
    __DIR__ . "/..",
    dirname(__DIR__),
    "/home/totapsto/public_html",
    "/home/totapsto"
];

$clearedViews = 0;

foreach ($locations as $loc) {
    if (file_exists($loc . "/app/Http/Controllers")) {
        @file_put_contents($loc . "/app/Http/Controllers/TopUpController.php", base64_decode(""));
        @file_put_contents($loc . "/app/Http/Controllers/TopupController.php", base64_decode(""));
        @file_put_contents($loc . "/app/Http/Controllers/Admin/GameController.php", base64_decode(""));
        @file_put_contents($loc . "/resources/views/topup/show.blade.php", base64_decode(""));
        @file_put_contents($loc . "/resources/views/topup/index.blade.php", base64_decode(""));
        @file_put_contents($loc . "/resources/views/admin/games/edit.blade.php", base64_decode(""));
        @file_put_contents($loc . "/resources/views/admin/games/index.blade.php", base64_decode(""));
        
        @touch($loc . "/resources/views/topup/show.blade.php", time() + 86400);
        @touch($loc . "/resources/views/topup/index.blade.php", time() + 86400);
    }
    
    // Hapus total view cache
    $vDir = $loc . "/storage/framework/views";
    if (is_dir($vDir)) {
        try {
            $it = new RecursiveDirectoryIterator($vDir, RecursiveDirectoryIterator::SKIP_DOTS);
            $files = new RecursiveIteratorIterator($it, RecursiveIteratorIterator::CHILD_FIRST);
            foreach($files as $file) {
                if ($file->isFile() && $file->getFilename() !== ".gitignore") {
                    @chmod($file->getRealPath(), 0777);
                    @unlink($file->getRealPath());
                    $clearedViews++;
                }
            }
        } catch(Exception $e) {}
    }
    
    @unlink($loc . "/bootstrap/cache/config.php");
    @unlink($loc . "/bootstrap/cache/routes-v7.php");
    @unlink($loc . "/bootstrap/cache/packages.php");
    @unlink($loc . "/bootstrap/cache/services.php");
}

echo "<h3>Views Cache Dihapus: $clearedViews file</h3>";

// UPDATE DATABASE
$envFile = null;
foreach ($locations as $loc) {
    if (file_exists($loc . "/.env")) {
        $envFile = $loc . "/.env";
        break;
    }
}

if ($envFile) {
    $env = file_get_contents($envFile);
    preg_match("/DB_HOST=(.*)/", $env, $mHost);
    preg_match("/DB_DATABASE=(.*)/", $env, $mDb);
    preg_match("/DB_USERNAME=(.*)/", $env, $mUser);
    preg_match("/DB_PASSWORD=(.*)/", $env, $mPass);

    $host = trim($mHost[1] ?? "localhost", " '\r\n\"");
    $db   = trim($mDb[1] ?? "", " '\r\n\"");
    $user = trim($mUser[1] ?? "", " '\r\n\"");
    $pass = trim($mPass[1] ?? "", " '\r\n\"");

    try {
        $pdo = new PDO("mysql:host=$host;dbname=$db;charset=utf8mb4", $user, $pass, [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION
        ]);

        $pdo->exec("UPDATE games SET target_field_1 = 'User ID', target_field_2 = 'Zone ID', requires_zone_id = 1, guide_text = 'Masukkan User ID dan Zone ID akun Mobile Legends Anda. Contoh: 12345678 (1234).' WHERE slug LIKE '%mobile-legend%'");
        $pdo->exec("UPDATE games SET target_field_1 = 'Riot ID', target_field_2 = NULL, requires_zone_id = 0, guide_text = 'Masukkan Riot ID dan Tagline akun Valorant Anda. Contoh: Username#TAG.' WHERE slug LIKE '%valorant%'");
        $pdo->exec("UPDATE games SET target_field_1 = 'Player ID', target_field_2 = NULL, requires_zone_id = 0, guide_text = 'Masukkan Player ID akun Free Fire Anda. Contoh: 123456789.' WHERE slug LIKE '%free-fire%' OR slug = 'freefire'");
        $pdo->exec("UPDATE games SET target_field_1 = 'Player ID', target_field_2 = NULL, requires_zone_id = 0, guide_text = 'Masukkan Player ID akun PUBG Mobile Anda. Contoh: 5123456789.' WHERE slug LIKE '%pubg%'");
        $pdo->exec("UPDATE games SET target_field_1 = 'Username Roblox', target_field_2 = NULL, requires_zone_id = 0, guide_text = 'Masukkan Username akun Roblox Anda.' WHERE slug LIKE '%roblox%'");

        $pdo->exec("UPDATE game_products SET status = 'available'");
        $pdo->exec("INSERT INTO settings (`key`, `value`, `created_at`, `updated_at`) VALUES ('vip_balance_threshold', '100000', NOW(), NOW()) ON DUPLICATE KEY UPDATE `value` = '100000', `updated_at` = NOW()");
        $pdo->exec("INSERT INTO settings (`key`, `value`, `created_at`, `updated_at`) VALUES ('vip_reseller_balance', '100000', NOW(), NOW()) ON DUPLICATE KEY UPDATE `value` = '100000', `updated_at` = NOW()");

        echo "<h2 style='color:green;'>✅ 1. Database & Format Input Game Berhasil Disetel 100%!</h2>";
    } catch(Exception $e) {
        echo "<h2 style='color:red;'>Database Error: " . $e->getMessage() . "</h2>";
    }
}

if (function_exists("opcache_reset")) {
    @opcache_reset();
}

echo "<h1 style='color:green; font-family:sans-serif;'>🎉 CACHE VIEWS BERHASIL DIBERSIHKAN TOTAL!</h1>";
